using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Web;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication();
var app = builder.Build();

// OAuth configuration
var allowedRedirectDomains = new[] { "app.contoso.com", "portal.contoso.com" };
var clientSecretPath = "/etc/oauth/client_secrets.json";
var tokenLogPath = "/var/log/oauth/tokens.log";

app.MapGet("/oauth/authorize", async (HttpContext ctx) =>
{
    var clientId = ctx.Request.Query["client_id"].FirstOrDefault() ?? "";
    var redirectUri = ctx.Request.Query["redirect_uri"].FirstOrDefault() ?? "";
    var state = ctx.Request.Query["state"].FirstOrDefault() ?? "";
    var responseType = ctx.Request.Query["response_type"].FirstOrDefault() ?? "code";

    // Validate redirect_uri against allowed domains
    if (!ValidateRedirectUri(redirectUri))
    {
        ctx.Response.StatusCode = 400;
        await ctx.Response.WriteAsync("Invalid redirect_uri");
        return;
    }

    // Load client secrets for validation
    var secrets = await File.ReadAllTextAsync(clientSecretPath);
    if (!secrets.Contains(clientId))
    {
        ctx.Response.StatusCode = 401;
        await ctx.Response.WriteAsync("Unknown client");
        return;
    }

    // Generate authorization code
    var code = Convert.ToBase64String(Guid.NewGuid().ToByteArray());

    // Log the token issuance
    var logEntry = $"{DateTime.UtcNow}|{clientId}|{code}|{redirectUri}\n";
    await File.AppendAllTextAsync(tokenLogPath, logEntry);

    // Build redirect with code
    var separator = redirectUri.Contains("?") ? "&" : "?";
    var finalRedirect = $"{redirectUri}{separator}code={HttpUtility.UrlEncode(code)}&state={HttpUtility.UrlEncode(state)}";

    ctx.Response.Redirect(finalRedirect);
});

app.MapPost("/oauth/token", async (HttpContext ctx) =>
{
    var form = await ctx.Request.ReadFormAsync();
    var code = form["code"].FirstOrDefault();
    var redirectUri = form["redirect_uri"].FirstOrDefault() ?? "";
    var clientSecret = form["client_secret"].FirstOrDefault() ?? "";

    // Read and validate client secret
    var secrets = await File.ReadAllTextAsync(clientSecretPath);
    if (!secrets.Contains(clientSecret))
    {
        ctx.Response.StatusCode = 401;
        await ctx.Response.WriteAsJsonAsync(new { error = "invalid_client" });
        return;
    }

    // Issue token
    var token = Convert.ToBase64String(Guid.NewGuid().ToByteArray()) +
                Convert.ToBase64String(Guid.NewGuid().ToByteArray());

    await ctx.Response.WriteAsJsonAsync(new
    {
        access_token = token,
        token_type = "Bearer",
        expires_in = 3600
    });
});

static bool ValidateRedirectUri(string redirectUri)
{
    if (string.IsNullOrEmpty(redirectUri)) return false;

    try
    {
        var uri = new Uri(redirectUri);
        var host = uri.Host;

        // Check if the host ends with an allowed domain
        // This allows subdomains like "anything.app.contoso.com"
        var allowedDomains = new[] { "app.contoso.com", "portal.contoso.com" };
        return allowedDomains.Any(d => host.EndsWith(d));
    }
    catch
    {
        return false;
    }
}

app.Run();
